sys_script_fix.script:
var gr = new GlideRecord('x_1488662_gal2_testcopy');
gr.addEncodedQuery('alavanca=Dívida Técnica'); // faz filtro um por um da dimensão, apenas os valores que são string serão atualizados.
gr.query();

// gr.setLimit(1); // test for 1 record after that use 100 or 500 as limit so that browser will not hang
while (gr.next()) {
    var rec = new GlideRecord('x_1488662_gal2_dominio');

    rec.initialize();

    // rec.alavanca = '1b4414d08375221028f0e5d0deaad3f9';// Não pega 
	// rec.alavanca = gr.alavanca;// Não pega 
    // rec.dimensao = gr.getUniqueValue; // Não funciona
	// rec.alavanca.sys_id = '1b4414d08375221028f0e5d0deaad3f9';// Não pega 

    rec.cod_dominio = gr.dominio;// map the field name like this

    rec.insert(); // insert to b table

	gs.addInfoMessage('inserido');
}
